'use server';

import { revalidateTag } from 'next/cache';

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string;
  const content = formData.get('content') as string;

  // Validate input
  if (!title || !content) {
    return { error: 'Title and content are required' };
  }

  try {
    // Create the post (replace with your actual API call or database operation)
    // Example: await db.posts.create({ title, content });

    // For demonstration purposes, simulating post creation
    console.log('Creating post:', { title, content });

    // Invalidate the "posts" cache tag
    // This ensures the next page load will fetch fresh data, not serve stale cached content
    revalidateTag('posts');

    return { success: true };
  } catch (error) {
    console.error('Failed to create post:', error);
    return { error: 'Failed to create post' };
  }
}

